// components/ReviewCard.jsx

import React from 'react';
import { Link } from 'react-router-dom';

function ReviewCard({ id, username, title, text, images = [], createdAt, likes = 0, comments = 0, tags = [], rating }) {
  const mainImage = images && images.length > 0 ? images[0] : null;

  return (
    <article className="card fade-in shimmer" style={{ marginBottom: 16, overflow: 'hidden', padding: 0 }}>
      {mainImage && (
        <div style={{ width: '100%', height: 260, overflow: 'hidden' }}>
          <img src={mainImage} alt={title || 'review'} className="tilt" style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
        </div>
      )}

      <div style={{ padding: 14 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 12 }}>
          <div style={{ flex: 1 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <div style={{ width: 40, height: 40, borderRadius: '50%', background: '#ddd', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 700, color: '#333' }}>{username?.slice(0,1) || 'U'}</div>
              <div>
                <div style={{ fontSize: 14, fontWeight: 700 }}>{username || '익명'}</div>
                <div style={{ fontSize: 12, color: '#999' }}>{createdAt ? new Date(createdAt).toLocaleDateString() : ''}</div>
              </div>
            </div>

            {title && <h3 style={{ margin: '10px 0 6px', fontSize: 16 }}>{title}</h3>}
            <p style={{ color: '#333', lineHeight: 1.6, margin: 0, marginBottom: 10, display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>{text}</p>

            <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', marginTop: 8 }}>
              {tags && tags.slice(0,3).map((t, i) => (
                <span key={i} style={{ background: 'rgba(11,87,164,0.08)', color: 'var(--primary)', padding: '4px 8px', borderRadius: 16, fontSize: 12 }}>{`#${t}`}</span>
              ))}
            </div>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 8 }}>
            <div style={{ fontSize: 14, color: 'var(--primary)', fontWeight: 800 }}>{rating ? `${rating} ★` : ''}</div>
            <Link to={`/review/${id}`} style={{ textDecoration: 'none' }}>
              <button className="btn" style={{ padding: '8px 12px', borderRadius: 8, border: '1px solid #eee', background: '#fafafa' }}>자세히 보기</button>
            </Link>
          </div>
        </div>

        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: 12 }}>
          <div style={{ color: '#777', fontSize: 13, display: 'flex', gap: 12, alignItems: 'center' }}>
            <span>❤️ {likes}</span>
            <span>💬 {comments}</span>
          </div>
        </div>
      </div>
    </article>
  );
}

export default ReviewCard;
